#!/usr/bin/env python3
"""Generate the assembler include (target.inc) for a target from its target.json."""
import json
import math
import os
import struct
import sys


def main(target, arm_internal, out):
    cfg = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "targets", target, "target.json")))
    h = lambda k: "$%X" % int(cfg[k], 16)
    ext = int(cfg["rom_extrom"], 16)
    t = lambda arm: "$%X" % (ext + arm - 0x08000000)
    lines = [
        "; generated by tools/gen_target_inc.py from targets/%s/target.json - do not edit" % target,
        "HLE_BASE\tequ\t%s" % h("hle_base"),
        "SHWIN\t\tequ\t%s" % h("reloc_base"),
        "SHWIN_SIZE\tequ\t%s" % h("reloc_size"),
        "HLEV\t\tequ\t%s" % h("hlev_base"),
        "SEQVAR\t\tequ\t%s" % h("seq_var"),
        "ECHOVAR\t\tequ\t%s" % h("echo_var"),
        "STATUSVAR\tequ\t%s" % h("status_var"),
        "POLLVAR\t\tequ\t%s" % h("poll_var"),
        "SEND_EXIT\tequ\t%s" % h("send_exit"),
        "VBLCNT\t\tequ\t%s" % h("vbl_counter"),
        "IDLE_RESUME\tequ\t%s" % h("idle_resume"),
        "SINTAB\t\tequ\t%s" % h("rom_sintab"),
        "AIMTAB\t\tequ\t%s" % h("rom_aimtab"),
        "AIMTAB_SIZE\tequ\t$%X" % (0x4000 - 0x2C90),
        "CTRLPTR\t\tequ\t%s" % h("rom_ctrlptr"),
        "MULCOST\t\tequ\t%s" % h("rom_mulcost"),
        "EXTROM\t\tequ\t%s" % h("rom_extrom"),
    ]
    for name, arm in (("T_ANIM", 0x080063E4), ("T_1714", 0x0800010C), ("T_1718", 0x08000100),
                      ("T_171C", 0x08007C2C), ("T_1720", 0x08006904), ("T_172C", 0x08007BEC),
                      ("T_19C4", 0x08007BFC), ("T_19C8", 0x08007C1C), ("T_1AE0", 0x08007C0C),
                      ("T_1AE4", 0x08007C24), ("T_TYPES", 0x080085A0), ("T_VANISH", 0x08000134)):
        lines.append("%s\t\tequ\t%s" % (name, t(arm)))
    # calibrated ARM response model (docs/timing.md): extra polls E = P - 1 for a reply
    # D cycles after the latch write, first poll at first_poll, then every poll_period
    tm = cfg["timing"]
    E = lambda d: max(0, math.ceil((d - tm["first_poll"]) / tm["poll_period"]))
    for k, v in tm["arm_cycles"].items():
        lines.append("E_CMD%s\t\tequ\t%d" % (k.upper(), E(v)))
    c12 = tm["cmd12"]
    tab = [E(c12["n0"] if n == 0 else c12["base"] + c12["per_request"] * n) for n in range(128)]
    lines.append("E12TAB_DATA\tmacro")
    for i in range(0, 128, 16):
        lines.append("\tdc.b\t" + ",".join(str(x) for x in tab[i:i + 16]))
    lines.append("\tendm")
    c14 = tm["cmd14_x10"]
    for k, v in c14.items():
        if k != "note":
            lines.append("C14_%s\t\tequ\t%d" % (k.upper(), v))
    lines.append("FIRST_POLL_X10\tequ\t%d" % (tm["first_poll"] * 10))
    # idle-loop phase lock: delay D for each r = (job cycles + idle_pre) mod period, such
    # that idle_pre + job + (r..) + D + rest = 0 mod period; D = delay_fix + 10k + 4m
    per, fix, sled = tm["idle_period"], tm["delay_fix"], tm["delay_sled"]
    lines.append("IDLE_PRE\tequ\t%d" % tm["idle_pre"])
    lines.append("DELAY_SLED\tequ\t%d" % sled)
    lines.append("IDLETAB_DATA\tmacro")
    words = []
    for r in range(0, per, 2):
        d = (-(r + tm["idle_after_r"])) % per
        while True:
            rest = d - fix
            sol = [(k, m) for m in range(sled + 1) for k in [(rest - 4 * m) // 10]
                   if rest - 4 * m >= 0 and (rest - 4 * m) % 10 == 0 and k < 256]
            if sol:
                k, m = sol[0]
                break
            d += per
        words.append((k << 8) | ((sled - m) * 2))
    for i in range(0, len(words), 12):
        lines.append("\tdc.w\t" + ",".join("$%04X" % w for w in words[i:i + 12]))
    lines.append("\tendm")
    lines.append("POLL_PERIOD_X10\tequ\t%d" % (tm["poll_period"] * 10))
    open(out, "w").write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main(*sys.argv[1:4])
